-- ============================================================================
-- Promptly: eksik içeriği tamamla (viral-reset.sql'den SONRA) — OTOMATİK ÜRETİLDİ.
-- Kaynak: supabase/seed/fill-content.mjs + fill-cases.json
--         node supabase/seed/build-fill-seed.mjs
--
-- HİÇBİR ŞEY SİLMEZ, yalnızca ekler. İki kez çalıştırılırsa ikinci seferde hata verip
-- hiçbir şey değiştirmez (tek transaction + "zaten uygulandı" kontrolü).
--
-- Ekler: 42 metin, 17 video, 14 ses promptu,
--        39 prompt isteği (7'inde gerçek yanıt), 60 generator, 12 workflow, beğeniler.
-- Kaynaklar: prompts.chat (CC0), awesome-ad-video-prompts (CC BY 4.0), awesome-ai-music-prompts (MIT),
--            Awesome Suno Resources (CC BY 4.0). Her açıklamada kaynak bağlantısı yer alır.
-- Supabase Dashboard → SQL Editor'e yapıştır, tek seferde çalıştır.
-- ============================================================================

begin;

do $guard$
begin
  if exists (select 1 from public.prompts where id = '5eed0001-0000-4000-8000-000000001000') then
    raise exception 'Bu seed zaten uygulanmış; işlem iptal edildi.';
  end if;
  if (select count(*) from auth.users where id in ('5eed0000-0000-4000-8000-000000000001', '5eed0000-0000-4000-8000-000000000002', '5eed0000-0000-4000-8000-000000000003', '5eed0000-0000-4000-8000-000000000004', '5eed0000-0000-4000-8000-000000000005', '5eed0000-0000-4000-8000-000000000006', '5eed0000-0000-4000-8000-000000000007', '5eed0000-0000-4000-8000-000000000008', '5eed0000-0000-4000-8000-000000000009', '5eed0000-0000-4000-8000-00000000000a', '5eed0000-0000-4000-8000-00000000000b', '5eed0000-0000-4000-8000-00000000000c', '5eed0000-0000-4000-8000-00000000000d', '5eed0000-0000-4000-8000-00000000000e', '5eed0000-0000-4000-8000-00000000000f', '5eed0000-0000-4000-8000-000000000010', '5eed0000-0000-4000-8000-000000000011', '5eed0000-0000-4000-8000-000000000012')) <> 18 then
    raise exception 'Beklenen % demo kullanıcının tamamı bulunamadı; işlem iptal edildi.', 18;
  end if;
end
$guard$;

