-- --- 7. Bildirimler: bu seed'in beğenileri/yanıtları trigger'larla bildirim üretti; hepsi
-- "şimdi" tarihli olmasın diye rastgele son 10 güne yayılıyor (eski bildirimlere dokunulmaz).
update public.notifications
set created_at = now() - (random() * interval '10 days'),
    is_read = random() < 0.6
where created_at = now() and recipient_id in ('5eed0000-0000-4000-8000-000000000001', '5eed0000-0000-4000-8000-000000000002', '5eed0000-0000-4000-8000-000000000003', '5eed0000-0000-4000-8000-000000000004', '5eed0000-0000-4000-8000-000000000005', '5eed0000-0000-4000-8000-000000000006', '5eed0000-0000-4000-8000-000000000007', '5eed0000-0000-4000-8000-000000000008', '5eed0000-0000-4000-8000-000000000009', '5eed0000-0000-4000-8000-00000000000a', '5eed0000-0000-4000-8000-00000000000b', '5eed0000-0000-4000-8000-00000000000c', '5eed0000-0000-4000-8000-00000000000d', '5eed0000-0000-4000-8000-00000000000e', '5eed0000-0000-4000-8000-00000000000f', '5eed0000-0000-4000-8000-000000000010', '5eed0000-0000-4000-8000-000000000011', '5eed0000-0000-4000-8000-000000000012');

-- --- 8. Kontrol ---------------------------------------------------------------------------
select content_type as tur, count(*) as prompt from public.prompts group by 1
union all select 'istek', count(*) from public.prompt_requests
union all select 'istek (yanıtlı)', count(*) from public.prompt_requests where response_count > 0
union all select 'generator', count(*) from public.generators
union all select 'workflow', count(*) from public.workflows
union all select 'workflow adımı', count(*) from public.workflow_steps
order by 1;

commit;

